#include "filter_barrier.h"
#include "oracle.h"
#include <assert.h>
#include <string.h>
#include <stdio.h>
static unsigned checks;
#define CHECK(x) do{checks++;assert(x);}while(0)
static void put(uint8_t*p,uint32_t n){for(unsigned i=0;i<4;i++)p[i]=(uint8_t)(n>>(8*i));}
static uint8_t ready[44];
static void ready_make(void){memset(ready,0,sizeof(ready));put(ready,2);put(ready+4,36|(35u<<16));put(ready+8,0x01000000);put(ready+12,574);put(ready+16,0x5f414351);put(ready+20,0x4c4d);ready[32]=2;ready[37]=1;}
static QcaHtcCredit ledger(void){QcaHtcCredit c={0};QcaHtcReady r={.credits=8,.credit_size=256,.endpoints=3};QcaHtcConnection w={.service=QCA_HTC_WMI,.max_bytes=4088,.endpoint=1};CHECK(qca_htc_credit_begin(&c,&r,&w));return c;}
static void begin(QcaFilterBarrier*s,QcaHtcCredit*c){memset(s,0,sizeof(*s));*c=ledger();CHECK(qca_filter_begin(s,c,ready,sizeof(ready),7,10,0x0ba991e9,100));}
/* Actual shared-owner mechanics modeled with the real HTC credit helpers.
 * Filter APIs are checked byte-for-byte never to write this ledger. */
static void publish(QcaFilterBarrier*s,QcaHtcCredit*c,unsigned id){QcaHtcCredit before=*c;CHECK(qca_filter_prepare(s,7,100+id));CHECK(!memcmp(c,&before,sizeof(*c)));CHECK(s->frame_bytes==(s->step==0?28u:12u));CHECK(qca_filter_submitted(s,7,id,100+id));uint8_t p[36];CHECK(qca_htc_header(p,sizeof(p),c->endpoint,s->frame_bytes,(uint8_t)id,1));memcpy(p+8,s->frame,s->frame_bytes);uint32_t ticket;CHECK(qca_htc_credit_reserve(c,s->frame_bytes+8,&ticket));CHECK(qca_htc_credit_commit(c,ticket));before=*c;CHECK(qca_filter_post(s,7,id,10,p,s->frame_bytes+8,100+id));CHECK(!memcmp(c,&before,sizeof(*c)));CHECK(!qca_filter_passed(s));}
static void three(QcaFilterBarrier*s,QcaHtcCredit*c){begin(s,c);for(unsigned id=1;id<=3;id++){publish(s,c,id);if(id<3)CHECK(qca_filter_tx_complete(s,7,id,s->frame_bytes+8,100+id));}CHECK(s->step==2&&s->tx_count==3&&s->echo_floor==10);}
static unsigned echo(uint8_t*p,uint32_t arg,unsigned endpoint,int credit){unsigned n=credit?28:20;memset(p,0,n);CHECK(qca_htc_header(p,n,endpoint,12+(credit?8:0),0,0));if(credit){p[1]=2;p[4]=8;p[20]=1;p[21]=4;p[24]=1;p[25]=1;}put(p+8,WMI_TLV_ECHO_EVENTID);put(p+12,4|(WMI_TLV_TAG_STRUCT_ECHO_EVENT<<16));put(p+16,arg);return n;}
static void wire_tests(void){const uint8_t mac[6]={2,0,0,0,0,1};uint8_t a[64],b[64];for(unsigned step=0;step<3;step++){unsigned n=ref_wire(step,b,mac,0xba991e9);CHECK(n==(step==0?28u:12u));for(unsigned cap=0;cap<50;cap++){memset(a,0xa5,sizeof(a));unsigned got=qca_filter_wire(step,a,cap,mac,0xba991e9);CHECK(got==(cap>=n?n:0));if(got)CHECK(!memcmp(a,b,n));for(unsigned i=got;i<sizeof(a);i++)CHECK(a[i]==0xa5);}}
CHECK(!qca_filter_wire(3,a,64,mac,1));CHECK(!qca_filter_wire(2,a,64,mac,0));CHECK(!qca_filter_wire(0,a,64,(uint8_t[6]){1},1));CHECK(!qca_filter_wire(0,a,64,(uint8_t[6]){0},1));CHECK(!qca_filter_wire(0,a,64,a+4,1));CHECK(!qca_filter_wire(2,(void*)(UINTPTR_MAX-3),64,mac,1));uint32_t v=0x55;uint8_t raw[32];echo(raw,0xba991e9,1,0);for(unsigned n=0;n<=31;n++){v=0x55;CHECK(qca_filter_echo_payload(raw+8,n,&v)==(n==12));CHECK(v==(n==12?0xba991e9u:0x55u));}CHECK(!qca_filter_echo_payload(raw+8,12,(void*)(raw+16)));
for(unsigned tag=0;tag<=65535;tag++){put(raw+12,4|(tag<<16));v=0x55;CHECK(qca_filter_echo_payload(raw+8,12,&v)==(tag==WMI_TLV_TAG_STRUCT_ECHO_EVENT));}
for(unsigned len=0;len<=65535;len++){put(raw+12,len|(WMI_TLV_TAG_STRUCT_ECHO_EVENT<<16));v=0x55;CHECK(qca_filter_echo_payload(raw+8,12,&v)==(len==4));}}
static void flows(void){QcaFilterBarrier s;QcaHtcCredit c;uint8_t raw[40];unsigned n;for(unsigned early=0;early<2;early++){three(&s,&c);n=echo(raw,s.echo_arg,1,1);QcaHtcFrame f;CHECK(qca_htc_decode(raw,n,&f));CHECK(qca_htc_credit_receive(&c,&f));QcaHtcCredit before=c;if(!early){CHECK(qca_filter_tx_complete(&s,7,3,20,104));CHECK(!qca_filter_passed(&s));}CHECK(qca_filter_receive(&s,7,11,2,raw,n,105)==1);CHECK(!memcmp(&c,&before,sizeof(c)));CHECK(qca_filter_passed(&s)==!early);if(early)CHECK(qca_filter_tx_complete(&s,7,3,20,106));CHECK(qca_filter_passed(&s));CHECK(s.raw_bytes==n&&s.raw_completion==11&&!memcmp(s.raw,raw,n));CHECK(qca_filter_poll(&s,7,10000000)==1);CHECK(qca_filter_receive(&s,7,12,2,raw,n,10000001)==-1);CHECK(!qca_filter_passed(&s));CHECK(!memcmp(&c,&before,sizeof(c)));}
for(unsigned fault=0;fault<9;fault++){three(&s,&c);n=echo(raw,s.echo_arg,1,0);QcaHtcCredit before=c;int rc=0;if(fault==0)put(raw+16,s.echo_arg+1);if(fault==1)raw[0]=2;if(fault==2)put(raw+12,4|(55u<<16));if(fault==3)rc=qca_filter_receive(&s,6,11,2,raw,n,105);else if(fault==4)rc=qca_filter_receive(&s,7,10,2,raw,n,105);else if(fault==5)rc=qca_filter_receive(&s,7,11,1,raw,n,105);else if(fault==6)rc=qca_filter_poll(&s,7,s.deadline);else if(fault==7)rc=qca_filter_poll(&s,7,1);else if(fault==8)rc=qca_filter_tx_complete(&s,7,3,19,105);else rc=qca_filter_receive(&s,7,11,2,raw,n,105);CHECK(rc<0);CHECK(s.phase==QCA_FILTER_FAULT&&!qca_filter_passed(&s));CHECK(!memcmp(&c,&before,sizeof(c)));if(fault<=2||fault==4||fault==5)CHECK(s.raw_bytes==n);}
begin(&s,&c);CHECK(qca_filter_prepare(&s,7,101));QcaHtcCredit before=c;CHECK(qca_filter_cancel_unposted(&s));CHECK(!memcmp(&c,&before,sizeof(c)));CHECK(!qca_filter_submitted(&s,7,1,102));begin(&s,&c);CHECK(qca_filter_prepare(&s,7,101));CHECK(qca_filter_submitted(&s,7,1,101));CHECK(!qca_filter_cancel_unposted(&s));before=c;uint8_t tx[36];CHECK(qca_htc_header(tx,36,1,28,0,1));memcpy(tx+8,s.frame,28);CHECK(qca_filter_post(&s,7,1,10,tx,36,102)<0);CHECK(!memcmp(&c,&before,sizeof(c)));three(&s,&c);n=echo(raw,s.echo_arg,1,0);put(raw+8,0x1d011);before=c;CHECK(qca_filter_receive(&s,7,11,2,raw,n,105)==0&&!s.echo_seen);CHECK(!memcmp(&c,&before,sizeof(c)));CHECK(!qca_filter_passed(&s));CHECK(qca_filter_poll(&s,7,s.deadline)<0);
/* Intentionally violate integration timing: refunded credit BEFORE post observation
 * must fail closed instead of blessing a guessed transmission. */
begin(&s,&c);CHECK(qca_filter_prepare(&s,7,101));CHECK(qca_filter_submitted(&s,7,1,101));CHECK(qca_htc_header(tx,36,1,28,0,1));memcpy(tx+8,s.frame,28);uint32_t ticket;CHECK(qca_htc_credit_reserve(&c,36,&ticket));CHECK(qca_htc_credit_commit(&c,ticket));QcaHtcFrame credit={.endpoint=0};credit.credits[1]=1;CHECK(qca_htc_credit_receive(&c,&credit));before=c;CHECK(qca_filter_post(&s,7,1,10,tx,36,102)<0);CHECK(s.error==12&&!qca_filter_passed(&s));CHECK(!memcmp(&c,&before,sizeof(c)));
QcaFilterBarrier alias={0},saved;QcaHtcCredit cc=ledger();memcpy((uint8_t*)&alias+128,&cc,sizeof(cc));saved=alias;CHECK(!qca_filter_begin(&alias,(void*)((uint8_t*)&alias+128),ready,44,7,10,1,100));CHECK(!memcmp(&alias,&saved,sizeof(alias)));
for(unsigned shortn=0;shortn<44;shortn++){memset(&s,0,sizeof(s));c=ledger();CHECK(!qca_filter_begin(&s,&c,ready,shortn,7,10,1,100));CHECK(!s.phase);}begin(&s,&c);CHECK(!qca_filter_prepare(&s,6,101));CHECK(s.phase==QCA_FILTER_FAULT);CHECK(!qca_filter_passed(&s));}
int main(void){ready_make();wire_tests();flows();printf("FILTER-BARRIER PASS %u checks; body-only/sharedcredit-readonly/actual-ECHO-contract; synthetic only\n",checks);return 0;}
